import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Return the sum of square(x) for each x in xs.

    The squares are computed concurrently on a ThreadPoolExecutor with
    `workers` threads. The result does not depend on `workers`.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError(f"workers must be >= 1, got {workers}")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_matches_serial() -> None:
    xs = list(range(-50, 51))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs) == expected


def test_sum_squares_same_at_every_worker_count() -> None:
    xs = [3, -1, 4, -1, 5, -9, 2, 6, -5, 3, 5]
    expected = sum(square(x) for x in xs)
    for workers in (1, 2, 3, 4, 8, 32):
        assert sum_squares(xs, workers=workers) == expected


def test_sum_squares_more_workers_than_items() -> None:
    assert sum_squares([2, 3], workers=16) == 13


def test_sum_squares_rejects_nonpositive_workers() -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=0)
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=-1)
